import{_ as o,o as a,c as l,a2 as r}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"篇785｜超脱者与制度·超脱者与锚点议事会的关系","description":"","frontmatter":{"title":"篇785｜超脱者与制度·超脱者与锚点议事会的关系","no":785,"module":4,"tags":["超脱","制度","锚点议事会","立法","万族代表"],"related":["0040-共生宪法总纲","0049-治理框架与权力制衡","784-超脱者与制度总论"]},"headers":[],"relativePath":"zh/0785_模块4-制度-超脱者与锚点议事会.md","filePath":"zh/0785_模块4-制度-超脱者与锚点议事会.md"}'),e={name:"zh/0785_模块4-制度-超脱者与锚点议事会.md"};function i(n,t,s,h,u,q){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="篇785-超脱者与制度·超脱者与锚点议事会的关系" tabindex="-1">篇785｜超脱者与制度·超脱者与锚点议事会的关系 <a class="header-anchor" href="#篇785-超脱者与制度·超脱者与锚点议事会的关系" aria-label="Permalink to &quot;篇785｜超脱者与制度·超脱者与锚点议事会的关系&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档40、49、784</p></blockquote><h2 id="引言-超脱者在立法机构里-只有一票" tabindex="-1">引言：超脱者在立法机构里，只有一票 <a class="header-anchor" href="#引言-超脱者在立法机构里-只有一票" aria-label="Permalink to &quot;引言：超脱者在立法机构里，只有一票&quot;">​</a></h2><p>锚点议事会是锚点共生文明的立法机构——万族一切法律、规则、公约，都由它讨论、表决、颁布。旧世界的超脱者天然是&quot;立法者&quot;——他说的话就是法。衡元宙必须明确：<strong>超脱者在锚点议事会里，不是议长，不是主席，只是一个有一票的普通代表。</strong> 本篇把这条关系钉死。</p><p>六大顶层公理在此刻同时压阵：反掠夺主义公理要求立法不含掠夺；万族共和公理要求立法权属于万族代表；集体升维公理要求立法服务于升维；因果自律公理要求立法不制造因果漏洞；法则优先公理要求立法程序自洽、不可被超脱者个人操纵。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、超脱者在议事会的三种权利" tabindex="-1">一、超脱者在议事会的三种权利 <a class="header-anchor" href="#一、超脱者在议事会的三种权利" aria-label="Permalink to &quot;一、超脱者在议事会的三种权利&quot;">​</a></h2><p>超脱者作为万族代表（按778篇的代表资格程序获得），在锚点议事会有三种权利：</p><ol><li><strong>提案权</strong>：超脱者可以向议事会提交法案提案。提案不需要别人附议，但也不自动进入议程——任何代表的提案都走同一程序</li><li><strong>表决权</strong>：超脱者在表决时投一票，和其他代表的一票等重。不存在&quot;超脱者票算两票&quot;</li><li><strong>发言权</strong>：超脱者可以在议事会发言，但发言时长和其他代表相同，不允许&quot;因为强就多讲半小时&quot;</li></ol><p>三种权利合起来，超脱者在议事会里就是&quot;一个稍微有点资历的代表&quot;。他的资历可以让他的提案更容易被重视，但不能让他的票更重。</p><h2 id="二、超脱者在议事会的三条限制" tabindex="-1">二、超脱者在议事会的三条限制 <a class="header-anchor" href="#二、超脱者在议事会的三条限制" aria-label="Permalink to &quot;二、超脱者在议事会的三条限制&quot;">​</a></h2><p>权利之外，还有三条限制：</p><ul><li><strong>无否决权</strong>：超脱者不能否决议事会通过的法案。法案一旦通过，超脱者也必须遵守</li><li><strong>无解散权</strong>：超脱者不能因为议事会&quot;不听话&quot;就解散它。议事会的存在由共生宪法保障</li><li><strong>无临时立法权</strong>：超脱者不能绕过议事会&quot;临时立法&quot;。任何规则变更必须走正常立法程序</li></ul><p>三条限制确保议事会始终是万族的立法机关，不是超脱者的橡皮图章。</p><h2 id="三、超脱者提案的特别程序" tabindex="-1">三、超脱者提案的特别程序 <a class="header-anchor" href="#三、超脱者提案的特别程序" aria-label="Permalink to &quot;三、超脱者提案的特别程序&quot;">​</a></h2><p>超脱者因为算力大、见识广，他的提案确实比普通代表更有技术含量。衡元宙为此设了&quot;超脱者提案特别程序&quot;，但这个程序是<strong>更严格</strong>而不是更宽松：</p><ol><li>超脱者提案必须附完整的技术论证（法则影响、因果扰动、万族覆盖评估）</li><li>提案必须经过至少一个完整审议周期，不能&quot;紧急通过&quot;</li><li>提案必须接受万族代表交叉质询，超脱者必须当场回答</li><li>提案表决时，超脱者必须回避自己主导的表决（利益冲突回避）</li></ol><p>特别程序的逻辑是：<strong>超脱者提案影响面大，所以更要慎审。</strong> 不是&quot;超脱者说话算数&quot;，而是&quot;超脱者说话更要被认真审&quot;。</p><h2 id="四、议事会对超脱者的反向权力" tabindex="-1">四、议事会对超脱者的反向权力 <a class="header-anchor" href="#四、议事会对超脱者的反向权力" aria-label="Permalink to &quot;四、议事会对超脱者的反向权力&quot;">​</a></h2><p>关系是双向的。超脱者在议事会里受限制，议事会对超脱者也有反向权力：</p><ul><li><strong>立法权约束超脱者</strong>：议事会通过的法律，超脱者必须遵守。他违反法律，议事会可以启动弹劾</li><li><strong>预算权约束超脱者</strong>：议事会审批超脱者岗位所需的公共算力、资源配额。超脱者&quot;要干活&quot;，必须议事会批预算</li><li><strong>监督权约束超脱者</strong>：议事会可以定期传唤超脱者，要求其汇报岗位绩效</li></ul><p>反向权力确保超脱者和议事会是互相约束的，不是超脱者单方面指挥议事会。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：旧世界让超脱者随口立法，等于把立法权浪费在个人意志上；衡元宙用程序把立法权交给万族代表</li><li><strong>反掠夺</strong>：立法权在议事会而不在超脱者，封死了&quot;强者立法掠夺弱者&quot;的路径</li><li><strong>唐罗上限对比</strong>：唐罗说什么就是什么；衡元宙要求唐罗在议事会里只有一票</li><li><strong>万族全覆盖</strong>：议事会代表万族五大谱系，超脱者不能代表任何一个族群垄断立法</li><li><strong>超多元全开放</strong>：议事会议事记录、法案全文通过无私道全网开放。超脱者在议事会的每一次投票、每一次提案都被阿赖耶网络记录，计入其文明权重</li><li><strong>全员无限均等</strong>：众生全员无限均等法则——锚点共生文明内人人自带基础无限之力，佛系懒狗保有保底基础无限、不被时代淘汰，卷王少年至尊可叠加更高层级无限；无限本源人人自带，掠夺自然失去意义</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>超脱者在锚点议事会里，不是议长，不是主席，只是一个有一票的普通代表。他可以提案，可以发言，可以表决，但不能否决，不能解散，不能临时立法。立法权属于万族代表，不属于任何一个人——哪怕那个人强到衡锚超多元境。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./0040-共生宪法总纲.html">0040-共生宪法总纲</a> · <a href="./0049-治理框架与权力制衡.html">0049-治理框架与权力制衡</a> · <a href="./0784_模块4-制度-总论.html">784-超脱者与制度总论</a> · <a href="./0778_模块4-万族-超脱者的代表资格.html">778-超脱者的万族代表资格</a></li></ul>',28)])])}const g=o(e,[["render",i]]);export{d as __pageData,g as default};
